class Solution:
    def maximumRows(self, matrix: List[List[int]], numSelect: int) -> int:
        m, n = len(matrix), len(matrix[0])
        rows = [sum(matrix[i][j] << j for j in range(n)) for i in range(m)]

        def cover(sel):
            return sum((r & sel) == r for r in rows)

        def bt(i, left, sel):
            if left == 0:
                return cover(sel)
            if n - i < left:
                return 0
            return max(bt(i + 1, left, sel),
                       bt(i + 1, left - 1, sel | (1 << i)))

        return bt(0, numSelect, 0)

