class Solution {
    private int[] rows;
    private int n;

    public int maximumRows(int[][] matrix, int numSelect) {
        int m = matrix.length;
        n = matrix[0].length;
        rows = new int[m];
        for (int i = 0; i < m; i++)
            for (int j = 0; j < n; j++)
                if (matrix[i][j] == 1) rows[i] |= 1 << j;
        return bt(0, numSelect, 0);
    }

    private int cover(int sel) {
        int c = 0;
        for (int r : rows) if ((r & sel) == r) c++;
        return c;
    }

    private int bt(int i, int left, int sel) {
        if (left == 0) return cover(sel);
        if (n - i < left) return 0;
        return Math.max(bt(i + 1, left, sel), bt(i + 1, left - 1, sel | (1 << i)));
    }
}

